-- Generated by scripts/run_snowflake.py (load_plan); the runner executes exactly these statements.
-- Loads data/raw/*.csv into FUNDLAKE.RAW as all-varchar tables with lineage columns, matching DuckDB's read_csv(all_varchar = true).
USE ROLE FUNDLAKE_ROLE; USE WAREHOUSE FUNDLAKE_WH; USE DATABASE FUNDLAKE;
CREATE SCHEMA IF NOT EXISTS RAW;
CREATE OR REPLACE FILE FORMAT RAW.CSV_FMT TYPE = CSV SKIP_HEADER = 1 FIELD_OPTIONALLY_ENCLOSED_BY = '"' NULL_IF = ('') EMPTY_FIELD_AS_NULL = TRUE;
CREATE OR REPLACE STAGE RAW.LANDING FILE_FORMAT = RAW.CSV_FMT;

-- custodian_cash_nav: 260 rows
PUT 'file://<repo>/data/raw/custodian_cash_nav.csv' @RAW.LANDING AUTO_COMPRESS = TRUE OVERWRITE = TRUE;
CREATE OR REPLACE TABLE RAW.CUSTODIAN_CASH_NAV (position_date VARCHAR, fund_id VARCHAR, cash_gbp VARCHAR, admin_nav_gbp VARCHAR, _SOURCE_FILE VARCHAR, _ROW_NUMBER NUMBER);
COPY INTO RAW.CUSTODIAN_CASH_NAV FROM (SELECT $1, $2, $3, $4, 'custodian_cash_nav.csv', METADATA$FILE_ROW_NUMBER FROM @RAW.LANDING/custodian_cash_nav.csv.gz) FILE_FORMAT = (FORMAT_NAME = RAW.CSV_FMT) ON_ERROR = ABORT_STATEMENT FORCE = TRUE;
UPDATE RAW.CUSTODIAN_CASH_NAV SET _ROW_NUMBER = _ROW_NUMBER - (SELECT MIN(_ROW_NUMBER) FROM RAW.CUSTODIAN_CASH_NAV) + 1;

